// Кейс: .qa/tests/monitoring/MON-026.md · план: .qa/e2e-app/specs/app.md (1.31)
// ПОЛУАВТОМАТ (@manual-assist): человек включает авиарежим через Пункт управления на ~30 с и выключает, потом жмёт Enter
// в терминале («готово»). В авиарежиме Appium теряет связь (socket hang up) → скрипт пересоздаёт сессию БЕЗ перезапуска
// приложения (App.reconnect) и проверяет: лист «הניטור הופסק» с «מרכז הבקרה» → «המשך ניטור» → «תקין»;
// в «היסטוריית אירועים» «החיבור נותק» и «משהו הסתיר את האפליקציה», на каждый сбой ровно одно «הניטור חזר לפעול»,
// нет «המצלמה הפסיקה לפעול», и за следующие 30 с «תקין» новых событий нет (баг #7b5462 — пара каждые ~8 с).
// Источник: «מה רצוי» #7b5462 + проверка 01.11 (נותק 0:01:35, הסתיר 0:02:01, חזר 0:02:05 и 0:02:18; скрины results/2026-11-01-7b5462-*.png).
// Только с BANCI_MONITORING=1 И BANCI_MANUAL_ASSIST=1 (без человека авиарежима не будет — пропуск).
import { createInterface } from 'node:readline/promises';
import { by, assert, skip } from '../../lib/appium.mjs';
import {
  requireMonitoringOptIn, startMonitoring, endMonitoring, waitTimer, timerSeconds,
  EV, FAILURE_EVENTS, collectEvents, countOf, fmtEvents,
} from '../../lib/monitoring.mjs';

export const name = 'Авиарежим 30 с: «החיבור נותק», «משהו הסתיר את האפליקציה», по одному «הניטור חזר לפעול» на сбой, без пар каждые 8 с #7b5462 @iphone @app @data @manual-assist';

async function waitHuman(prompt) {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = rl.question(prompt);
    const limit = new Promise((_, rej) => setTimeout(() => rej(new Error('человек не подтвердил «готово» за 10 мин')), 600000));
    await Promise.race([answer, limit]);
  } finally {
    rl.close();
  }
}

export default async function (app) {
  requireMonitoringOptIn();
  if (process.env.BANCI_MANUAL_ASSIST !== '1') skip('полуавтомат: авиарежим включает человек — запуск только с BANCI_MANUAL_ASSIST=1 (и BANCI_MONITORING=1)');
  await startMonitoring(app);
  await waitTimer(app, 5);

  // 1. Человек: авиарежим через Пункт управления ~30 с → выключить → Enter.
  await waitHuman(
    '\n     СЕЙЧАС: откройте Пункт управления (свайп из правого верхнего угла) → включите авиарежим → закройте Пункт управления,\n' +
    '     подождите ~30 с → снова Пункт управления → выключите авиарежим → закройте его. В Banci ничего не нажимайте.\n' +
    '     Дождитесь, пока вернётся Wi-Fi/сеть, и нажмите Enter («готово»): ',
  );

  // 2. Связь с Appium после авиарежима — новая сессия без перезапуска приложения.
  if (!(await app.alive())) {
    console.log('     сессия Appium потеряна (авиарежим) → новая сессия без перезапуска Banci');
    await app.reconnect();
  }

  // 3. Лист «הניטור הופסק» называет «מרכז הבקרה» → «המשך ניטור».
  await app.waitFor(by.contains('הניטור הופסק'), { timeout: 15000, what: 'лист «הניטור הופסק» после Пункта управления' });
  await app.waitFor(by.contains('מרכז הבקרה'), { what: 'текст листа про «מרכז הבקרה» («משהו הסתיר את Banci (מרכז הבקרה, שיחה או חלון מערכת)…»)' });
  console.log(`     лист → ${await app.screenshot('7b5462-auto-airplane-sheet').catch(() => '—')}`);
  await app.tap(by.exact('המשך ניטור', 'Button'), { what: '«המשך ניטור» в листе' });
  await app.waitGone(by.contains('הניטור הופסק'), { what: 'лист «הניטור הופסק» закрылся' });
  await app.waitFor(by.exact('תקין'), { timeout: 30000, what: 'статус «תקין» после выключения авиарежима' });

  // 4. События сбоя и возврата.
  const before = await collectEvents(app);
  console.log(`     события: ${fmtEvents(before)}`);
  for (const ev of [EV.DISCONNECTED, EV.HIDDEN]) {
    assert(countOf(before, ev) >= 1, `в «היסטוריית אירועים» есть «${ev}» (есть: ${fmtEvents(before)})`);
  }
  const failures = FAILURE_EVENTS.reduce((n, ev) => n + countOf(before, ev), 0);
  const resumed = countOf(before, EV.RESUMED);
  assert(resumed === failures, `на каждый сбой ровно одно «${EV.RESUMED}»: сбоев ${failures}, возвратов ${resumed} (${fmtEvents(before)})`);
  assert(countOf(before, EV.CAMERA_STOPPED) === 0, `«${EV.CAMERA_STOPPED}» нет (${fmtEvents(before)})`);

  // 5. Ещё 30 с при «תקין» — новых событий нет (раньше пара «המצלמה הפסיקה לפעול»/«הניטור חזר לפעול» каждые ~8 с).
  await waitTimer(app, (await timerSeconds(app)) + 30, { timeout: 60000 });
  const after = await collectEvents(app);
  const shot = await app.screenshot('7b5462-auto-airplane-events').catch(() => undefined);
  const added = after.filter((e) => !before.some((b) => b.title === e.title && b.time === e.time));
  assert(!added.length, `за 30 с при «תקין» новых событий нет (новые: ${fmtEvents(added)}; скрин ${shot ?? '—'})`);

  // 6. Завершить мониторинг (сеанс в истории — тестовые данные); число событий в итоге — только в лог.
  await endMonitoring(app);
  const total = await app.findAll(by.contains('אירועים', 'StaticText')).catch(() => []);
  for (const e of total) console.log(`     итог: ${await e.attr('label')}`);
}
